SELECT DISTINCT t.task_id AS taskId, s.flow_status AS flowStatus, s.current_handler_id AS handlerId, d.dept_id AS handlerDeptId, d.dept_name AS handlerDeptName FROM biz_task t JOIN biz_material_submission s ON (s.task_id=t.task_id OR s.task_id IN (SELECT c.task_id FROM biz_level4_task c WHERE c.parent_id=t.task_id AND COALESCE(c.is_delete,0)=0)) LEFT JOIN sys_user u ON u.user_id=s.current_handler_id AND u.is_delete=0 LEFT JOIN sys_dept d ON d.dept_id=u.dept_id AND d.is_delete=0 WHERE t.level=3 AND COALESCE(t.is_delete,0)=0 AND (s.is_delete=0 OR s.flow_status < 0) AND s.sub_id=(SELECT MAX(n.sub_id) FROM biz_material_submission n WHERE n.task_id=s.task_id) AND t.task_id IN (${ids})